def lucide(name: str, size: int = 18, color: str = "currentColor", stroke: float = 2.0, class_name: str = "") -> str:
    """
    Renders an inline Lucide SVG icon adhering to shadcn/ui design conventions.
    
    Args:
        name: Name of the icon (e.g., 'shield-check', 'zap', 'database', 'lock').
        size: Width and height in px (default: 18).
        color: Stroke color (default: 'currentColor').
        stroke: Stroke width (default: 2.0).
        class_name: Additional CSS classes.
    
    Returns:
        HTML string containing the inline SVG.
    """
    name_clean = name.strip().lower()
    template = LUCIDE_SVGS.get(name_clean)
    if not template:
        template = LUCIDE_SVGS["shield"]
    return template.format(size=size, color=color, stroke=stroke, cls=class_name)
